import { Context } from './context.js';
export class Application extends Context {
    constructor(label) {
        super();
        this.label = label;
    }
    async init() {
        if (this.isInitialized) {
            return this;
        }
        try {
            await Promise.resolve();
            this.isInitialized = true;
        }
        finally {
            this.flushed = true;
        }
        return this;
    }
    name() {
        return 'application ' + this.label;
    }
}
